def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        return ()
    version_nums = []
    current_num = None
    for ch in s:
        if ch.isdigit():
            if current_num is None:
                current_num = int(ch)
            else:
                current_num = current_num * 10 + int(ch)
        else:
            if current_num is not None:
                version_nums.append(current_num)
                current_num = None
    if current_num is not None:
