def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    parts = []
    current = ""
    for ch in s:
        if ch.isdigit():
            current += ch
        else:
            if current:
                parts.append(current)
                current = ""
    if current:
        parts.append(current)
    # Convert captured numeric parts to integers, ignoring any that are empty
    try:
        return tuple(int(p) for p in parts if p)
    except ValueError:
        # In the unlikely event that non-representable integer strings are present,
        # return an empty tuple as a safe fallback
        return ()

