                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []
    # `key_regex` and `value_regex` are expected to be defined in the module
    # where this function is placed.
    for key, value in labels.items():
        # Validate key type
