        kind = resource.get('kind', 'UnknownKind')
        metadata = resource.get('metadata', {})
        name = metadata.get('name', 'unknown-name')
        namespace = metadata.get('namespace', '')

        # Create a unique identifier for the resource
        if namespace:
            resource_id = f"{kind}:{namespace}/{name}"
        else:
            resource_id = f"{kind}:{name}"

        # Generate default schema only if one is not already defined
        if resource_id not in existing_schemas:
