    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    if not isinstance(folder, str):
        raise TypeError(f"Folder must be a string, got {type(folder).__name__}")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist or is not a directory")

    data = {}
    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                name, ext = os.path.splitext(entry)
                ext = ext.lower()
                if ext == ".xml":
                    # Start a new group for this XML file
                    group = {ext: [full_path]}
                    # Look for other files with the same basename
                    for other in os.listdir(folder):
                        if other == entry:
                            continue
                        other_full_path = os.path.join(folder, other)
                        if os.path.isfile(other_full_path):
                            other_name, other_ext = os.path.splitext(other)
                            if other_name == name:
                                other_ext_lower = other_ext.lower()
                                group.setdefault(other_ext_lower, []).append(other_full_path)
                    data[name] = group
    except Exception as e:
        raise RuntimeError(f"Error exploring folder '{folder}': {e}")

    return data

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import glob
    import xml.etree.ElementTree as ET

    result = {}
    if not isinstance(folder, str) or not os.path.isdir(folder):
        return result

    try:
        # Collect all files in the folder and its subdirectories
        all_files = glob.glob(os.path.join(folder, '**'), recursive=True)
        # Filter out directories
        all_files = [f for f in all_files if os.path.isfile(f)]
    except Exception:
        return result

    # Group by basename without extension
    groups = {}
    for path in all_files:
        try:
            filename = os.path.basename(path)
            base, ext = os.path.splitext(filename)
            groups.setdefault(base, []).append((ext.lower(), path))
        except Exception:
            continue

    # Assemble result dict
    for base, files in groups.items():
        pkg = {'files': []}
        # Find XML file first
        xml_content = None
        for ext, path in files:
            if ext == '.xml':
                try:
                    tree = ET.parse(path)
                    xml_content = ET.tostring(tree.getroot(), encoding='unicode')
                except Exception:
                    xml_content = None
                break
        if xml_content:
            pkg['xml'] = xml_content
        # Add other files except the xml one
        for ext, path in files:
            if ext != '.xml':
                pkg['files'].append(path)
