    use_ssl = parsed.scheme == "https"

    # Determine image_id from the last non-empty segment of the path
    path = parsed.path
    if not path:
        raise ValueError("URL path is empty; cannot determine image_id")
    if path.endswith("/"):
        path = path[:-1]
    image_id = path.rsplit("/", 1)[-1]
    if not image_id:
        raise ValueError("Could not extract image_id from URL path")

    netloc = parsed.netloc
    return (image_id, netloc, use_ssl)

