            parsed = urllib.parse.urlparse(f"//{rest}")  # add a dummy scheme
        else:
            raise ValueError(f"Invalid image href '{image_href}': missing scheme")

    # Validate scheme – only http/https are allowed
    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme '{parsed.scheme}' in image href '{image_href}'")

    use_ssl = parsed.scheme == "https"
    # Trim leading slash from path to make image_id relative
    image_id = parsed.path.lstrip("/")
    netloc = parsed.netloc

    return (image_id, netloc, use_ssl)

