def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments into control and nested arguments.

    Parameters
    ----------
    args : dict | list | tuple
        The collected list or dictionary of arguments. Arguments can be
        specified as:
          * simple dictionary {key: value}
          * list/tuple of strings in the form "key=value" or
            tuples/lists of two elements (key, value).

    Returns
    -------
    tuple
        Two dictionaries:
          * control_args: arguments whose keys start with a control prefix.
          * nested_args: all remaining arguments (including custom ones).

    Notes
    -----
    * Control prefixes are defined as ``control_``, ``ctl_`` and ``ansible_``;
      any argument whose key starts with one of these prefixes is considered
      a control argument.
    * All other arguments are treated as nested arguments.  Custom arguments
      are expected to be specified using a convention distinct from
      control prefixes and are therefore merged into the nested arguments.

    """
    # Define the prefixes that indicate control arguments
    control_prefixes = ("control_", "ctl_", "ansible_")

    # Initialize result dictionaries
    control_args = {}
    nested_args = {}

    # If args are falsy (None, empty, etc.), simply return empty dicts
    if not args:
        return control_args, nested_args

    # Helper to iterate over key/value pairs
    def iterate_args(arg_source):
        if isinstance(arg_source, dict):
            for k, v in arg_source.items():
                yield k, v
        elif isinstance(arg_source, (list, tuple)):
            for item in arg_source:
                if isinstance(item, str):
                    if "=" in item:
                        k, v = item.split("=", 1)
                        yield k.strip(), v.strip()
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    k, v = item
                    yield str(k), str(v)

    # Process each argument
    try:
        for k, v in iterate_args(args):
            if any(k.startswith(prefix) for prefix in control_prefixes):
                control_args[k] = v
            else:
                nested_args[k] = v
    except Exception:
        # On any exception, return whatever has been collected so far
        return control_args, nested_args

    return control_args, nested_args

