    # Ensure root is a prefix of path and aligns on a path separator
    if not path_norm.startswith(root_norm):
        raise ValueError(f"Root '{root_norm}' is not a prefix of path '{path_norm}'")

    # After the root, there must be a separator or nothing
    after = path_norm[len(root_norm) :]
    if after and not after.startswith(os.path.sep):
        raise ValueError(
            f"Root '{root_norm}' does not align correctly with path '{path_norm}'"
        )

    # Strip the leading separator if present
    if after and after[0] == os.path.sep:
        after = after[1:]

    return after

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Basic type checks
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    # If the root is the same as the path, return empty string
    if path == root:
        return ''
    # Normalise separators for comparison: allow both '/' and '\\'
    # Determine the root separator (if any)
    if root.endswith('/') or root.endswith('\\'):
        root_prefix = root
    else:
        root_prefix = root + '/'
    # Check if path starts with the root prefix
    if not path.startswith(root_prefix):
        # Special case: root might be the full path without trailing slash
        if path.startswith(root) and len(root) == len(path):
            return ''
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    # Remove the root from the path
    stripped = path[len(root_prefix):]
    # Strip leading separator if present
    if stripped and (stripped[0] == '/' or stripped[0] == '\\'):
        stripped = stripped[1:]
    return stripped
